# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VAAZ (İSLAMİ İRŞAT KONUŞMASI) VE TEMEL BÖLÜMLERİ</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Giriş (Mukaddime)</text>\n  <text x="40" y="103" font-size="11" fill="#334155">• Eûzü-Besmele</text>\n  <text x="40" y="125" font-size="11" fill="#334155">• Hamdele (Allah\'a hamd)</text>\n  <text x="40" y="147" font-size="11" fill="#334155">• Salvele (Peygamberimize</text>\n  <text x="50" y="164" font-size="10.5" fill="#475569">salât ve selâm)</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Cemaate samimi hitap ve</text>\n  <text x="50" y="203" font-size="10.5" fill="#1e40af" font-weight="bold">konuya dikkat çekici giriş</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Gelişme (Konu Sunumu)</text>\n  <text x="262" y="103" font-size="11" fill="#334155">• Ayet-i kerime ve sahih</text>\n  <text x="272" y="120" font-size="10.5" fill="#475569">hadislerle konunun izahı</text>\n  <text x="262" y="145" font-size="11" fill="#334155">• Günlük hayattan örnekler,</text>\n  <text x="272" y="162" font-size="10.5" fill="#475569">kıssalar ve çözüm önerileri</text>\n  <text x="262" y="187" font-size="11" fill="#334155">• Müjdeleyici (tebşîr) ve</text>\n  <text x="272" y="204" font-size="10.5" fill="#166534" font-weight="bold">kolaylaştırıcı (teysîr) üslup</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Sonuç ve Dua (Hâtime)</text>\n  <text x="485" y="103" font-size="11" fill="#334155">• Ana mesajın birkaç cümle</text>\n  <text x="495" y="120" font-size="10.5" fill="#475569">ile özlü biçimde toparlanması</text>\n  <text x="485" y="148" font-size="11" fill="#334155">• Cemaatle birlikte içten</text>\n  <text x="495" y="165" font-size="10.5" fill="#475569">ve kuşatıcı vaaz duası</text>\n  <text x="485" y="192" font-size="11" fill="#334155">• Fâtiha talebi ile kürsüden</text>\n  <text x="495" y="209" font-size="10.5" fill="#b45309" font-weight="bold">vakarla inilmesi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VAAZ HAZIRLAMA AŞAMALARI VE KAYNAK KULLANIM İLKELERİ</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Vaaz Hazırlık Süreci</text>\n  <text x="50" y="105" font-size="11.5" fill="#334155">1. Hedef kitlenin (cemaatin) ve zamanın</text>\n  <text x="62" y="123" font-size="11" fill="#475569">ihtiyacına uygun güncel/özgül konu seçimi</text>\n  <text x="50" y="148" font-size="11.5" fill="#334155">2. Konunun sınırlandırılması ve amacın tespiti</text>\n  <text x="50" y="173" font-size="11.5" fill="#334155">3. Sahih kaynaklardan (Kur\'an, muteber tefsir</text>\n  <text x="62" y="191" font-size="11" fill="#475569">ve sahih hadis kaynakları) materyal taraması</text>\n  <text x="50" y="216" font-size="11.5" font-weight="bold" fill="#1e40af">4. Vaaz planı ve kürsü notu hazırlanması</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Vaazda Kaçınılması Gereken Hatalar</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• Uydurma (mevzû) rivayet, hurafe ve</text>\n  <text x="392" y="123" font-size="11" fill="#475569">kaynağı belirsiz menkıbeler anlatmak</text>\n  <text x="380" y="148" font-size="11.5" fill="#334155">• Kişileri veya grupları hedef alarak kırıcı,</text>\n  <text x="392" y="166" font-size="11" fill="#475569">azarlayıcı ve ümit kırıcı bir dil kullanmak</text>\n  <text x="380" y="191" font-size="11.5" fill="#334155">• Konudan konuya dağılmak ve ezan/namaz</text>\n  <text x="392" y="209" font-size="11" fill="#475569">vaktini taşıracak şekilde süreyi uzatmak</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KÜRSÜ ÂDÂBI, BEDEN DİLİ VE HUTBE-VAAZ KARŞILAŞTIRMASI</text>\n  <rect x="35" y="55" width="300" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Kürsü Âdâbı ve Hitabet İlkeleri</text>\n  <text x="50" y="108" font-size="11" fill="#334155">• Temiz ve vakur kıyafet (cübbe ve sarık)</text>\n  <text x="50" y="130" font-size="11" fill="#334155">• Göz teması, doğal jest ve mimikler</text>\n  <text x="50" y="152" font-size="11" fill="#334155">• Vurgu ve tonlamayı konunun duygusuna</text>\n  <text x="62" y="170" font-size="11" fill="#475569">göre ayarlamak (tekdüzelikten kaçınmak)</text>\n  <text x="50" y="195" font-size="11" font-weight="bold" fill="#166534">• &quot;Kolaylaştırınız, zorlaştırmayınız; müjdeleyiniz,</text>\n  <text x="62" y="212" font-size="11" font-weight="bold" fill="#166534">nefret ettirmeyiniz!&quot; (Hadis-i Şerif)</text>\n  <rect x="365" y="55" width="300" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Vaaz ile Hutbe Arasındaki Farklar</text>\n  <text x="380" y="108" font-size="11" fill="#334155">• Yeri: Vaaz kürsüde oturarak; hutbe ise</text>\n  <text x="392" y="126" font-size="11" fill="#475569">minberde ayakta irad edilir.</text>\n  <text x="380" y="150" font-size="11" fill="#334155">• Hükmü: Cuma hutbesi namazın sıhhat</text>\n  <text x="392" y="168" font-size="11" fill="#475569">şartıdır (farzdır); vaaz ise irşat faaliyetidir.</text>\n  <text x="380" y="192" font-size="11" fill="#334155">• Süresi: Hutbe kısa ve öz (10-15 dk), vaaz</text>\n  <text x="392" y="210" font-size="11" fill="#475569">ise namaz öncesi daha geniş açıklamalıdır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
